<span class="line"><span style="color:#B31D28;font-style:italic;">    database</span><span style="color:#24292E;">: </span><span style="color:#B31D28;font-style:italic;">process.env.PROD_DB_NAME</span><span style="color:#24292E;">,</span></span>
