<span class="line"><span style="color:#D73A49;">    return</span><span style="color:#24292E;"> queryInterface.</span><span style="color:#6F42C1;">bulkDelete</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;Users&#39;</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">null</span><span style="color:#24292E;">, {});</span></span>
